<?php
namespace Tests\Feature;
use App\Models\Booking;use App\Models\Branch;use App\Models\Customer;use App\Models\Organization;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Tests\TestCase;
class ApiWorkdayTest extends TestCase{use RefreshDatabase;public function test_technician_api_only_returns_own_bookings_for_today():void{$org=Organization::create(['public_id'=>Str::uuid(),'name'=>'App AS']);$branch=Branch::create(['public_id'=>Str::uuid(),'organization_id'=>$org->id,'name'=>'Hoved','code'=>'H']);$tech=User::factory()->create(['organization_id'=>$org->id,'branch_id'=>$branch->id,'role'=>'technician','active'=>true]);$other=User::factory()->create(['organization_id'=>$org->id,'branch_id'=>$branch->id,'role'=>'technician','active'=>true]);$customer=Customer::create(['public_id'=>Str::uuid(),'organization_id'=>$org->id,'branch_id'=>$branch->id,'customer_number'=>'K1','name'=>'Kunde']);foreach([[$tech->id,now(),'MIN-I-DAG'],[$tech->id,now()->addDay(),'MIN-I-MORGEN'],[$other->id,now(),'ANNENS-I-DAG']]as[$user,$start,$ref])Booking::create(['public_id'=>Str::uuid(),'organization_id'=>$org->id,'branch_id'=>$branch->id,'assigned_user_id'=>$user,'customer_id'=>$customer->id,'reference'=>$ref,'service_name'=>'Skift','starts_at'=>$start,'ends_at'=>$start->copy()->addMinutes(45)]);$plain=Str::random(64);DB::table('personal_access_tokens')->insert(['user_id'=>$tech->id,'name'=>'app','abilities'=>json_encode(['read']),'token_hash'=>hash('sha256',$plain),'created_at'=>now(),'updated_at'=>now()]);$this->withToken($plain)->getJson('/api/v1/bookings')->assertOk()->assertSee('MIN-I-DAG')->assertDontSee('MIN-I-MORGEN')->assertDontSee('ANNENS-I-DAG');$this->withToken($plain)->getJson('/api/v1/workday')->assertOk()->assertJsonPath('data.assigned_bookings.0.reference','MIN-I-DAG');}}
